103	
104	  const std::vector<std::string>& getPieceHashes() const
105	  {
106	    return pieceHashes_;
107	  }
108	
109	  template <typename InputIterator>
110	  void setPieceHashes(const std::string& hashType, InputIterator first,
111	                      InputIterator last)
112	  {
