131	  {
132	    assert(!fileEntries_.empty());
133	    return fileEntries_[0];
134	  }
135	
136	  // This function returns first FileEntry whose isRequested() returns
137	  // true.  If there is no such FileEntry, returns
138	  // std::shared_ptr<FileEntry>().
139	  std::shared_ptr<FileEntry> getFirstRequestedFileEntry() const;
140	
